<script setup>
import { ref,computed,watch,onMounted,onUnmounted,nextTick } from 'vue';
import { useRoute,useRouter } from 'vue-router';
import {renderArticle} from './articleMarkdown.js';
import SearchBox from './SearchBox.vue';
import PostPreview from './PostPreview.vue';
import {safeReturnPath} from './authNavigation.js';
import {readingNavigation} from './navigation.js';
const route=useRoute(),router=useRouter();
const data=ref(null),taxonomy=ref({categories:[],tags:[]}),user=ref(null),error=ref(''),loading=ref(true),comment=ref(''),reply=ref(null),progress=ref(0),focus=ref(false),csrf=ref(''),username=ref(''),password=ref(''),showPassword=ref(false),registerNickname=ref(''),passwordConfirmation=ref(''),feedTab=ref('latest'),community=ref({series:[]}),trends=ref([]),pending=ref(false),profileTab=ref('posts'),expandedReplies=ref({});
let loadGeneration=0;
const pageKey=computed(()=>route.path+'?'+new URLSearchParams(route.query).toString());
const exploring=computed(()=>kind.value==='list');
const hasSearch=computed(()=>Object.keys(route.query).some(k=>['q','tagId','categoryId'].includes(k)));
async function searchTerm(q){router.push({path:'/articles',query:q?{q}:{}})}
const kind=computed(()=>route.path==='/'?'home':route.path==='/articles'?'list':route.path.startsWith('/articles/')?'article':route.path.startsWith('/users/')?'author':route.path==='/login'?'login':route.path==='/register'?'register':'favorites');
async function api(path,options={}){const r=await fetch('/api'+path,{credentials:'same-origin',...options,headers:{...(options.body?{'Content-Type':'application/json'}:{}),...(options.method?{'X-CSRF-Token':csrf.value}:{}),...options.headers}});const result=await r.json();if(!r.ok){if(r.status===401 && path!=='/auth/login')user.value=null;throw Object.assign(new Error(result.message||'请求失败'),{status:r.status})}return result.data}
async function token(){try{csrf.value=(await api('/auth/csrf')).token}catch(e){if(e.status!==401)throw e;csrf.value=(await api('/auth/csrf')).token}}
async function load(){const generation=++loadGeneration;let nextData=null;loading.value=true;error.value='';data.value=null;try{if(kind.value==='home'){const [home,feed]=await Promise.all([api('/home'),api('/articles?page='+encodeURIComponent(route.query.page||'1'))]);nextData={...home,feed}}if(kind.value==='list'){nextData=await api('/articles?'+new URLSearchParams(route.query));trends.value=await api('/trends')}if(kind.value==='article'){const [article,comments]=await Promise.all([api('/articles/'+route.params.id),api('/articles/'+route.params.id+'/comments?page='+encodeURIComponent(route.query.commentPage||'1')+'&targetId='+encodeURIComponent(route.query.commentId||''))]);nextData={article,comments};const root=comments.items.find(c=>c.id===String(route.query.commentId)||c.replies.some(r=>r.id===String(route.query.commentId)));if(root && route.query.commentId)expandedReplies.value={...expandedReplies.value,[root.id]:true}}if(kind.value==='author'){const [profile,articles,series,replies]=await Promise.all([api('/users/'+route.params.id+'/profile'),api('/articles?'+new URLSearchParams({authorId:route.params.id,page:route.query.page||'1'})),api('/users/'+route.params.id+'/series'),api('/users/'+route.params.id+'/replies?page='+encodeURIComponent(route.query.replyPage||'1'))]);nextData={profile,articles,series,replies}}if(kind.value==='favorites')nextData=await api('/me/favorites?'+new URLSearchParams(route.query));}catch(e){if(generation===loadGeneration){error.value=e.message;if(e.status===401 && kind.value==='favorites')router.replace({path:'/login',query:{next:route.fullPath}})}}finally{if(generation!==loadGeneration)return;data.value=nextData;loading.value=false;await nextTick();updateProgress();if(readingNavigation.restoreScroll!==null){const top=readingNavigation.restoreScroll;readingNavigation.restoreScroll=null;requestAnimationFrame(()=>window.scrollTo({top,behavior:'instant'}))}if(route.hash){try{document.getElementById(decodeURIComponent(route.hash.slice(1)))?.scrollIntoView()}catch{}}}}
watch(()=>route.path+'?'+new URLSearchParams(route.query).toString(),load);
watch(()=>route.path,()=>{focus.value=false;comment.value='';reply.value=null;password.value='';showPassword.value=false;passwordConfirmation.value=''});
onMounted(async()=>{window.addEventListener('scroll',updateProgress,{passive:true});try{await token();user.value=await api('/auth/me');taxonomy.value=await api('/taxonomy');community.value=await api('/home');trends.value=await api('/trends')}catch(e){error.value=e.message}await load()});
onUnmounted(()=>window.removeEventListener('scroll',updateProgress));
function updateProgress(){const el=document.querySelector('.article-body');if(!el){progress.value=0;return}const r=el.getBoundingClientRect();progress.value=Math.max(0,Math.min(100,Math.round((window.innerHeight-r.top)/Math.max(r.height,1)*100)))}
const rendered=computed(()=>renderArticle(data.value?.article?.bodyMarkdown||''));
async function action(fn){if(pending.value)return;pending.value=true;error.value='';try{await fn()}catch(e){error.value=e.message;if(e.status===401 && !['login','register'].includes(kind.value))router.push({path:'/login',query:{next:route.fullPath}})}finally{pending.value=false}}
async function login(){await action(async()=>{await token();const result=await api('/auth/login',{method:'POST',body:JSON.stringify({username:username.value.trim(),password:password.value})});csrf.value=result.csrfToken;user.value=result.user;password.value='';await router.replace(safeReturnPath(route.query.next))})}
async function register(){await action(async()=>{if(password.value!==passwordConfirmation.value)throw new Error('两次输入的密码不一致');await token();const result=await api('/auth/register',{method:'POST',body:JSON.stringify({username:username.value.trim(),nickname:registerNickname.value.trim(),password:password.value,passwordConfirmation:passwordConfirmation.value})});csrf.value=result.csrfToken;user.value=result.user;password.value='';passwordConfirmation.value='';await router.replace(safeReturnPath(route.query.next))})}
async function logout(){await action(async()=>{await api('/auth/logout',{method:'POST'});user.value=null;password.value='';await token();router.replace('/')})}

function requireUser(){if(!user.value){router.push({path:'/login',query:{next:route.fullPath}});return false}return true}
async function favorite(id,on){if(!requireUser())return;await action(async()=>{await api('/articles/'+id+'/favorite',{method:on?'PUT':'DELETE'});if(kind.value==='article' && data.value?.article?.id===id)data.value.article.favorited=on;else if(kind.value==='favorites'){data.value.items=data.value.items.filter(item=>item.id!==id);data.value.total=Number(data.value.total)-1;if(!data.value.items.length && data.value.page>1)changePage(data.value.page-1)}})}
async function reloadComments(){if(data.value?.article){const comments=await api('/articles/'+route.params.id+'/comments?page='+encodeURIComponent(route.query.commentPage||'1')+'&targetId='+encodeURIComponent(route.query.commentId||''));data.value.comments=comments}}
async function submit(){if(!requireUser())return;await action(async()=>{const posted=await api('/articles/'+route.params.id+'/comments',{method:'POST',body:JSON.stringify({content:comment.value,replyToId:reply.value?.id})});if(posted.rootId)expandedReplies.value={...expandedReplies.value,[posted.rootId]:true};comment.value='';const wasReply=!!reply.value;reply.value=null;if(!wasReply && Number(route.query.commentPage||1)!==1)await router.push({query:{...route.query,commentPage:'1'},hash:'#comments'});else await reloadComments();await nextTick();document.querySelector('#comments')?.scrollIntoView()})}
async function remove(id){await action(async()=>{await api('/comments/'+id,{method:'DELETE'});await reloadComments()})}

function chooseReply(target){if(!requireUser())return;reply.value=target;nextTick(()=>{const input=document.getElementById('comment');input?.focus();input?.scrollIntoView({block:'center'})})}
function toggleReplies(id){expandedReplies.value={...expandedReplies.value,[id]:!expandedReplies.value[id]}}
function backToFeed(){readingNavigation.restoreScroll=readingNavigation.returnScroll;router.push(readingNavigation.returnTo)}
function changePage(p){router.push({query:{...route.query,page:String(p)}})}
function changeCommentPage(p){router.push({query:{...route.query,commentPage:String(p),commentId:undefined},hash:'#comments'}).then(()=>nextTick(()=>document.querySelector('#comments')?.scrollIntoView()))}
function search(e){const fd=new FormData(e.target);router.push({path:'/articles',query:Object.fromEntries([...fd].filter(([,v])=>v))})}
</script>
<template>
  <div :class="{focused:focus, 'social-shell':true}">
    <div v-if="kind==='article'" class="progress" :style="{width:progress+'%'}" aria-hidden="true"></div>
    <aside class="social-sidebar" aria-label="主导航">
      <RouterLink to="/" class="social-brand"><span class="brand-mark">o<span>.</span></span><strong>OnlyCampus</strong></RouterLink>
      <nav class="social-nav">
        <RouterLink v-if="user" to="/me/notifications" aria-label="站内通知"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M5 17h14l-2-3V9a5 5 0 0 0-10 0v5zM10 21h4"/></svg><span>通知</span></RouterLink>
        <RouterLink v-if="user?.role==='ADMIN'" to="/admin" aria-label="管理后台"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z"/></svg><span>管理后台</span></RouterLink>
        <RouterLink to="/" :class="{'nav-current':kind==='home'}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M3 10.5 12 3l9 7.5V20a1 1 0 0 1-1 1h-5v-6H9v6H4a1 1 0 0 1-1-1z"/></svg><span>首页</span></RouterLink>
        <RouterLink to="/articles" :class="{'nav-current':exploring}"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/></svg><span>探索</span></RouterLink>
        <RouterLink :to="user?'/me/favorites':'/login?next=/me/favorites'"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M6 3.5h12v17L12 17l-6 3.5z" stroke-linejoin="round"/></svg><span>收藏</span></RouterLink>
        <RouterLink v-if="!user" to="/login"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><circle cx="12" cy="8" r="3.5"/><path d="M5 20c.5-4 3-6 7-6s6.5 2 7 6"/></svg><span>登录</span></RouterLink>
        <RouterLink v-else :to="'/users/'+user.id" class="nav-profile"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7"><path d="M10 4H5v16h5M14 8l4 4-4 4M8 12h10"/></svg><span>个人中心</span></RouterLink>
      </nav>
      <RouterLink :to="user?'/users/'+user.id:'/login'" class="social-account" aria-label="个人中心"><span class="avatar avatar-user">{{user?.nickname?.slice(0,1)||'我'}}</span><strong>{{user?.nickname||'个人中心'}}</strong></RouterLink>
    </aside>
    <main class="social-main center-column"><div v-if="error" class="notice" role="alert">{{error}} <button class="link-button" @click="load">重试</button></div><Transition name="page" appear><div v-if="loading" key="skeleton" class="page-skeleton" role="status" aria-label="页面加载中"><div v-for="n in 3" :key="n" class="skeleton-post" aria-hidden="true"><span class="skeleton-avatar"></span><div><span class="skeleton-line skeleton-name"></span><span class="skeleton-line"></span><span class="skeleton-line skeleton-short"></span></div></div></div><div v-else :key="pageKey" class="page-content">
    <template v-if="kind==='home' && data">
      <div class="home-content">
        <section class="feed" aria-label="校园文章">
          <header class="feed-header"><h1>首页</h1><RouterLink class="mobile-search-link" to="/articles" aria-label="搜索文章"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8"><circle cx="10.8" cy="10.8" r="6.8"/><path d="m16 16 4.5 4.5"/></svg></RouterLink><div class="feed-tabs"><button :class="{selected:feedTab==='latest'}" @click="feedTab='latest'">最新</button><button :class="{selected:feedTab==='featured'}" @click="feedTab='featured'">精选</button></div></header>
          <div class="feed-context"><span class="context-dot"></span><span>校园里的新鲜事</span><RouterLink to="/articles">探索更多 <span aria-hidden="true">→</span></RouterLink></div>
          <div class="feed-posts">
            <PostPreview v-for="a in (feedTab==='latest'?data.feed.items:data.featured)" :key="a.id" :post="a"/>
            <p v-if="!(feedTab==='latest'?data.feed.items:data.featured).length" class="feed-empty">暂无文章</p>
          </div>
          <div v-if="feedTab==='latest' && (data.feed.page>1 || data.feed.page*data.feed.pageSize<Number(data.feed.total))" class="pagination"><button :disabled="data.feed.page<=1" @click="changePage(data.feed.page-1)">上一页</button><span>{{data.feed.page}}</span><button :disabled="data.feed.page*data.feed.pageSize>=Number(data.feed.total)" @click="changePage(data.feed.page+1)">下一页</button></div>
        </section>

      </div>
    </template>
    <template v-else-if="kind==='list' && data"><header class="explore-header"><SearchBox :value="String(route.query.q||'')" @search="searchTerm"/></header><section v-if="!hasSearch" class="trend-list"><h1>热搜榜</h1><RouterLink v-for="(t,index) in trends" :key="t.term" :to="{path:'/articles',query:{q:t.term}}" class="trend-row"><span>{{index+1}}</span><div><strong>{{t.term}}</strong><p>{{t.count}} 次搜索</p></div></RouterLink><p v-if="!trends.length" class="empty">还没有热门搜索</p></section><div v-if="hasSearch" class="search-results"><h1 class="visually-hidden">搜索结果</h1><nav class="feed-tabs search-tabs" aria-label="搜索结果排序"><button :class="{selected:route.query.sort!=='updated'}" @click="router.push({query:{...route.query,sort:'latest',page:'1'}})">最新</button><button :class="{selected:route.query.sort==='updated'}" @click="router.push({query:{...route.query,sort:'updated',page:'1'}})">最近更新</button></nav><div v-if="route.query.categoryId || route.query.tagId" class="active-search-filter"><span>{{taxonomy.categories.find(c=>c.id===route.query.categoryId)?.name || taxonomy.tags.find(t=>t.id===route.query.tagId)?.name || '筛选结果'}}</span><button @click="router.push({path:'/articles',query:route.query.q?{q:route.query.q}:{}})">清除筛选</button></div><PostPreview v-for="a in data.items" :key="a.id" :post="a"/><div v-if="!data.items.length" class="search-empty"><h2>没有找到相关帖子</h2><p>试试其他关键词。</p></div><nav v-if="data.page>1 || data.page*data.pageSize<Number(data.total)" class="pagination" aria-label="搜索结果分页"><button :disabled="data.page<=1" @click="changePage(data.page-1)">上一页</button><span>{{data.page}}</span><button :disabled="data.page*data.pageSize>=Number(data.total)" @click="changePage(data.page+1)">下一页</button></nav></div></template>
    <template v-else-if="kind==='article' && data"><div class="reading-toolbar post-detail-toolbar"><button class="back-button" aria-label="返回帖子流" @click="backToFeed">←</button><h1>帖子</h1><button @click="focus=!focus">{{focus?'退出专注阅读':'专注阅读'}}</button></div><article class="article-layout"><div><header class="article-header detail-author"><RouterLink :to="'/users/'+data.article.authorId" class="avatar">{{data.article.author?.slice(0,1)}}</RouterLink><div><RouterLink :to="'/users/'+data.article.authorId" class="post-author">{{data.article.author}}</RouterLink></div></header><h2 class="detail-title">{{data.article.title}}</h2><div class="article-body" v-html="rendered.html"></div><time class="detail-date" :datetime="data.article.publishedAt">{{new Date(data.article.publishedAt).toLocaleString('zh-CN')}}</time><div class="article-actions detail-actions"><a href="#comments" class="detail-comment-action"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6"><path d="M20 11.5a7.8 7.8 0 0 1-8 7.5 8.8 8.8 0 0 1-3-.5L4 20l1.3-4A7.2 7.2 0 0 1 4 11.5 7.8 7.8 0 0 1 12 4a7.8 7.8 0 0 1 8 7.5Z"/></svg><span>评论 {{data.comments.total}}</span></a><button :disabled="pending" :aria-pressed="data.article.favorited" @click="favorite(data.article.id,!data.article.favorited)"><svg viewBox="0 0 24 24" :fill="data.article.favorited?'currentColor':'none'" stroke="currentColor" stroke-width="1.6"><path d="M6 3.5h12v17L12 17l-6 3.5z" stroke-linejoin="round"/></svg><span>{{data.article.favorited?'已收藏':'收藏'}}</span></button></div><nav v-if="data.article.series && (data.article.series.previous || data.article.series.next)" class="chapter-nav" aria-label="专栏文章导航"><RouterLink v-if="data.article.series.previous" :to="'/articles/'+data.article.series.previous.id"><small>上一篇</small><strong>{{data.article.series.previous.title}}</strong></RouterLink><span v-else></span><RouterLink v-if="data.article.series.next" :to="'/articles/'+data.article.series.next.id"><small>下一篇</small><strong>{{data.article.series.next.title}}</strong></RouterLink></nav><section id="comments" class="comments"><h2 class="visually-hidden">评论</h2><form class="reply-composer" @submit.prevent="submit"><label for="comment">{{reply?'回复 @'+reply.nickname:'发布你的回复'}}</label><textarea id="comment" v-model="comment" maxlength="500" rows="4" placeholder="发布你的回复"></textarea><div><button class="primary" :disabled="pending || !comment.trim()">{{pending?'正在提交…':'发表评论'}}</button> <button v-if="reply" type="button" @click="reply=null">取消回复</button></div></form><div v-for="c in data.comments.items" :key="c.id" :id="'comment-'+c.id" class="comment"><strong>{{c.nickname}}</strong><time class="comment-time" :datetime="c.createdAt">{{new Date(c.createdAt).toLocaleString('zh-CN')}}</time><p>{{c.content||'该评论已不可见'}}</p><button v-if="c.status==='VISIBLE'" @click="chooseReply(c)">回复</button><button v-if="user && c.userId===user.id && c.status==='VISIBLE'" @click="remove(c.id)">删除</button><button v-if="c.replies.length>1" class="expand-replies" :aria-expanded="!!expandedReplies[c.id]" @click="toggleReplies(c.id)">{{expandedReplies[c.id]?'收起回复':'展开 '+c.replies.length+' 条回复'}}</button><div v-for="r in (c.replies.length<=1 || expandedReplies[c.id] ? c.replies : [])" :key="r.id" :id="'comment-'+r.id" class="reply"><strong>{{r.nickname}}</strong><time class="comment-time" :datetime="r.createdAt">{{new Date(r.createdAt).toLocaleString('zh-CN')}}</time><p><RouterLink v-if="r.replyToNickname" :to="'/users/'+r.replyToUserId" class="reply-mention">@{{r.replyToNickname}} </RouterLink>{{r.content||'该评论已不可见'}}</p><button v-if="r.status==='VISIBLE'" @click="chooseReply(r)">回复</button><button v-if="user && r.userId===user.id && r.status==='VISIBLE'" @click="remove(r.id)">删除</button></div></div><p v-if="!data.comments.items.length" class="empty">{{Number(data.comments.total) ? '此页没有评论，请返回上一页。' : '还没有评论，来分享第一个想法。'}}</p><nav v-if="Number(data.comments.total)>data.comments.pageSize || data.comments.page>1" class="pagination" aria-label="评论分页"><button :disabled="data.comments.page<=1" @click="changeCommentPage(data.comments.page-1)">上一页</button><span>第 {{data.comments.page}} 页</span><button :disabled="data.comments.page*data.comments.pageSize>=Number(data.comments.total)" @click="changeCommentPage(data.comments.page+1)">下一页</button></nav></section></div></article></template>
    <template v-else-if="kind==='author' && data"><header class="profile-topbar"><RouterLink to="/" class="back-button" aria-label="返回首页">←</RouterLink><div><h1>{{data.profile.nickname}}</h1><span>{{data.articles.total}} 帖子</span></div></header><div class="profile-cover" aria-hidden="true"></div><section class="profile-identity"><div class="profile-avatar-row"><span class="avatar profile-avatar">{{data.profile.nickname?.slice(0,1)}}</span><button v-if="user && String(user.id)===String(data.profile.id)" class="profile-logout" @click="logout">退出登录</button></div><h2>{{data.profile.nickname}}</h2><p class="profile-bio">{{data.profile.bio||'还没有填写个人简介。'}}</p><div class="profile-stats"><span><strong>{{data.articles.total}}</strong> 帖子</span><span><strong>{{data.series.length}}</strong> 公开专栏</span><RouterLink v-if="user && String(user.id)===String(data.profile.id)" to="/me/favorites">我的收藏</RouterLink></div></section><nav class="feed-tabs profile-tabs" aria-label="个人主页内容"><button :class="{selected:profileTab==='posts'}" @click="profileTab='posts'">帖子</button><button :class="{selected:profileTab==='replies'}" @click="profileTab='replies'">回复</button><button :class="{selected:profileTab==='series'}" @click="profileTab='series'">专栏</button></nav><section v-if="profileTab==='posts'" class="profile-posts"><PostPreview v-for="a in data.articles.items" :key="a.id" :post="a"/><p v-if="!data.articles.items.length" class="empty">暂时没有公开帖子。</p><nav v-if="Number(data.articles.total)>data.articles.pageSize || data.articles.page>1" class="pagination" aria-label="作者文章分页"><button :disabled="data.articles.page<=1" @click="changePage(data.articles.page-1)">上一页</button><span>{{data.articles.page}}</span><button :disabled="data.articles.page*data.articles.pageSize>=Number(data.articles.total)" @click="changePage(data.articles.page+1)">下一页</button></nav></section><section v-else-if="profileTab==='replies'" class="profile-replies"><article v-for="item in data.replies.items" :key="item.id" class="profile-reply-item"><RouterLink :to="'/users/'+data.profile.id" class="post-author">{{data.profile.nickname}}</RouterLink><time class="comment-time">{{new Date(item.createdAt).toLocaleString('zh-CN')}}</time><p><RouterLink v-if="item.replyToNickname" :to="'/users/'+item.replyToUserId" class="reply-mention">@{{item.replyToNickname}} </RouterLink>{{item.content}}</p><RouterLink :to="{path:'/articles/'+item.articleId,query:{commentId:item.id},hash:'#comment-'+item.id}" class="reply-source">{{item.articleTitle}}</RouterLink></article><p v-if="!data.replies.items.length" class="empty">暂无公开回复。</p><nav v-if="data.replies.page>1 || data.replies.page*data.replies.pageSize<data.replies.total" class="pagination" aria-label="个人回复分页"><button :disabled="data.replies.page<=1" @click="router.push({query:{...route.query,replyPage:String(data.replies.page-1)}})">上一页</button><span>{{data.replies.page}}</span><button :disabled="data.replies.page*data.replies.pageSize>=data.replies.total" @click="router.push({query:{...route.query,replyPage:String(data.replies.page+1)}})">下一页</button></nav></section><section v-else class="profile-series"><div v-for="series in data.series" :key="series.id" class="series-row"><div><strong>{{series.name}}</strong><p>{{series.description}}</p></div></div><p v-if="!data.series.length" class="empty">暂时没有公开专栏。</p></section></template>
    <template v-else-if="kind==='favorites' && data"><section class="page-intro"><h1>我的收藏</h1></section><div v-for="a in data.items" :key="a.id" class="favorite-row"><div><RouterLink v-if="a.available" :to="'/articles/'+a.id"><h3>{{a.title}}</h3><p>{{a.summary}}</p></RouterLink><p v-else>文章已不可用</p></div><button :disabled="pending" @click="favorite(a.id,false)">取消收藏</button></div><p v-if="!data.items.length" class="empty">还没有收藏文章。</p><div class="pagination"><button :disabled="data.page<=1" @click="changePage(data.page-1)">上一页</button><span>第 {{data.page}} 页</span><button :disabled="data.page*data.pageSize>=data.total" @click="changePage(data.page+1)">下一页</button></div></template>
    <template v-else-if="kind==='login'"><section class="login user-login"><h1>登录 OnlyCampus</h1><form @submit.prevent="login"><label for="login-username">账号</label><input id="login-username" v-model="username" autocomplete="username" autocapitalize="none" spellcheck="false" minlength="4" maxlength="24" pattern="[A-Za-z0-9_]{4,24}" placeholder="输入账号" required :disabled="pending"><label for="login-password">密码</label><div class="password-field"><input id="login-password" v-model="password" :type="showPassword?'text':'password'" autocomplete="current-password" minlength="8" maxlength="64" placeholder="输入密码" required :disabled="pending"><button type="button" :aria-pressed="showPassword" :aria-label="showPassword?'隐藏密码':'显示密码'" @click="showPassword=!showPassword">{{showPassword?'隐藏':'显示'}}</button></div><button class="primary" :disabled="pending || !username.trim() || !password">{{pending?'正在登录…':'登录'}}</button></form><RouterLink :to="{path:'/register',query:route.query.next?{next:route.query.next}:{}}" class="auth-switch">还没有账号？注册</RouterLink><RouterLink v-if="user" :to="'/users/'+user.id" class="login-profile-link">已登录，进入个人主页</RouterLink></section></template>
    <template v-else-if="kind==='register'"><section class="login user-login"><h1>加入 OnlyCampus</h1><form @submit.prevent="register"><label for="register-username">账号</label><input id="register-username" v-model="username" autocomplete="username" minlength="4" maxlength="24" pattern="[A-Za-z0-9_]{4,24}" placeholder="4—24位字母、数字或下划线" required :disabled="pending"><label for="register-nickname">昵称</label><input id="register-nickname" v-model="registerNickname" autocomplete="nickname" minlength="2" maxlength="30" placeholder="你的校园昵称" required :disabled="pending"><label for="register-password">密码</label><input id="register-password" v-model="password" :type="showPassword?'text':'password'" autocomplete="new-password" minlength="8" maxlength="64" placeholder="8—64位密码" required :disabled="pending"><label for="register-confirm">确认密码</label><input id="register-confirm" v-model="passwordConfirmation" :type="showPassword?'text':'password'" autocomplete="new-password" minlength="8" maxlength="64" placeholder="再次输入密码" required :disabled="pending"><button type="button" class="register-password-toggle" :aria-pressed="showPassword" @click="showPassword=!showPassword">{{showPassword?'隐藏密码':'显示密码'}}</button><button class="primary" :disabled="pending || !username.trim() || !registerNickname.trim() || !password || !passwordConfirmation">{{pending?'正在注册…':'注册并登录'}}</button></form><RouterLink :to="{path:'/login',query:route.query.next?{next:route.query.next}:{}}" class="auth-switch">已有账号？登录</RouterLink></section></template>
    </div></Transition></main><aside class="social-discover shared-discover" aria-label="探索内容"><SearchBox v-if="!exploring" @search="searchTerm"/><section class="discover-block"><h2>浏览分类</h2><RouterLink v-for="c in taxonomy.categories" :key="c.id" :to="{path:'/articles',query:{categoryId:c.id}}" class="discover-link"><span>{{c.name}}</span><span aria-hidden="true">→</span></RouterLink></section><section v-if="community.series.length" class="discover-block"><h2>成长专栏</h2><div v-for="s in community.series" :key="s.id" class="discover-series"><RouterLink :to="'/users/'+s.authorId">{{s.name}}</RouterLink><p>{{s.description}}</p></div></section></aside>
  </div>
</template>
